export const MAPPED_THEME_PARKS = PARQUES_TEMATICOS_JSON.map((park) => {
  const baseFallback = FALLBACK_IMAGES[park.ubicacion.pais] || FALLBACK_IMAGES['DEFAULT'];
  return {
    id: `tp_${park.puesto}`,
    position: park.puesto,
    name: park.nombre,
    subtitle: `${park.ubicacion.localidad}, ${park.ubicacion.pais}`,
    image: `${baseFallback}&park_id=${park.puesto}`,
    score: +(park.puntuacion / 10).toFixed(2),
    trend: 'stable' as const,
    tipo: park.tipo,
    gestor: park.gestor
  };
});

